#define STATS_DIR APP_SD_MOUNT_POINT "/stats"
#define STATS_FILE_MAX (512*1024)
#define STATS_VERSION 1
static const char *TAG="stats";

typedef struct {char date[11];app_energy_totals_t totals;app_stats_slot_t slots[APP_STATS_SLOT_COUNT];bool valid;} day_data_t;
static SemaphoreHandle_t s_mutex;static app_config_t s_cfg;static day_data_t s_today,s_yesterday;static bool s_have_prev,s_task_started;static app_energy_sample_t s_prev;static int64_t s_last_save_us;

static void date_for(time_t t,char out[11]){struct tm tmv;localtime_r(&t,&tmv);strftime(out,11,"%Y-%m-%d",&tmv);}
static int slot_for(time_t t){struct tm tmv;localtime_r(&t,&tmv);return tmv.tm_hour*12+tmv.tm_min/5;}
static void yesterday_for(time_t now,char out[11]){struct tm tmv;localtime_r(&now,&tmv);tmv.tm_mday--;tmv.tm_isdst=-1;time_t p=mktime(&tmv);date_for(p,out);}
static void add(app_energy_totals_t *a,const app_energy_totals_t *b){a->production_kwh+=b->production_kwh;a->consumption_kwh+=b->consumption_kwh;a->grid_import_kwh+=b->grid_import_kwh;a->grid_export_kwh+=b->grid_export_kwh;a->battery_charge_kwh+=b->battery_charge_kwh;a->battery_discharge_kwh+=b->battery_discharge_kwh;}
static app_energy_totals_t energy(const app_energy_sample_t *a,const app_energy_sample_t *b,double h){app_energy_totals_t e={0};double pv=(a->power_pv_kw+b->power_pv_kw)*.5,load=(a->power_full_kw+b->power_full_kw)*.5,grid=(a->power_grid_kw+b->power_grid_kw)*.5,bat=(a->power_bat_kw+b->power_bat_kw)*.5;e.production_kwh=pv*h;e.consumption_kwh=load*h;if(grid>=0)e.grid_import_kwh=grid*h;else e.grid_export_kwh=-grid*h;if(bat>=0)e.battery_discharge_kwh=bat*h;else e.battery_charge_kwh=-bat*h;return e;}
static void avg(app_stats_slot_t *sl,const app_energy_sample_t *s){sl->sample_count++;float n=(float)sl->sample_count;sl->pv_kw+=((float)s->power_pv_kw-sl->pv_kw)/n;sl->load_kw+=((float)s->power_full_kw-sl->load_kw)/n;sl->grid_kw+=((float)s->power_grid_kw-sl->grid_kw)/n;sl->battery_kw+=((float)s->power_bat_kw-sl->battery_kw)/n;sl->valid=true;}
static void path_for(const char *d,char *out,size_t n){snprintf(out,n,STATS_DIR "/%s.json",d);}
static cJSON *tot_json(const app_energy_totals_t *t){cJSON *o=cJSON_CreateObject();cJSON_AddNumberToObject(o,"production_kwh",t->production_kwh);cJSON_AddNumberToObject(o,"consumption_kwh",t->consumption_kwh);cJSON_AddNumberToObject(o,"grid_import_kwh",t->grid_import_kwh);cJSON_AddNumberToObject(o,"grid_export_kwh",t->grid_export_kwh);cJSON_AddNumberToObject(o,"battery_charge_kwh",t->battery_charge_kwh);cJSON_AddNumberToObject(o,"battery_discharge_kwh",t->battery_discharge_kwh);return o;}
static bool tot_parse(cJSON *o,app_energy_totals_t *t){if(!cJSON_IsObject(o))return false;const char *n[]={"production_kwh","consumption_kwh","grid_import_kwh","grid_export_kwh","battery_charge_kwh","battery_discharge_kwh"};double *d[]={&t->production_kwh,&t->consumption_kwh,&t->grid_import_kwh,&t->grid_export_kwh,&t->battery_charge_kwh,&t->battery_discharge_kwh};for(int i=0;i<6;i++){cJSON *v=cJSON_GetObjectItemCaseSensitive(o,n[i]);if(!cJSON_IsNumber(v)||v->valuedouble<0)return false;*d[i]=v->valuedouble;}return true;}
static cJSON *day_json(const day_data_t *d){cJSON *r=cJSON_CreateObject();cJSON_AddNumberToObject(r,"version",STATS_VERSION);cJSON_AddStringToObject(r,"date",d->date);cJSON_AddItemToObject(r,"totals",tot_json(&d->totals));cJSON *a=cJSON_AddArrayToObject(r,"slots");for(int i=0;i<APP_STATS_SLOT_COUNT;i++){const app_stats_slot_t *s=&d->slots[i];cJSON *o=cJSON_CreateObject();cJSON_AddBoolToObject(o,"valid",s->valid);cJSON_AddNumberToObject(o,"count",s->sample_count);cJSON_AddNumberToObject(o,"pv",s->pv_kw);cJSON_AddNumberToObject(o,"load",s->load_kw);cJSON_AddNumberToObject(o,"grid",s->grid_kw);cJSON_AddNumberToObject(o,"battery",s->battery_kw);cJSON_AddItemToObject(o,"energy",tot_json(&s->energy));cJSON_AddItemToArray(a,o);}return r;}
static bool day_parse(cJSON *r,const char *date,day_data_t *out){if(!cJSON_IsObject(r))return false;cJSON *v=cJSON_GetObjectItemCaseSensitive(r,"version"),*d=cJSON_GetObjectItemCaseSensitive(r,"date"),*t=cJSON_GetObjectItemCaseSensitive(r,"totals"),*a=cJSON_GetObjectItemCaseSensitive(r,"slots");if(!cJSON_IsNumber(v)||v->valueint!=STATS_VERSION||!cJSON_IsString(d)||strcmp(d->valuestring,date)||!cJSON_IsArray(a)||cJSON_GetArraySize(a)!=APP_STATS_SLOT_COUNT)return false;day_data_t x={0};snprintf(x.date,sizeof(x.date),"%s",date);if(!tot_parse(t,&x.totals))return false;for(int i=0;i<APP_STATS_SLOT_COUNT;i++){cJSON *o=cJSON_GetArrayItem(a,i);cJSON *valid=cJSON_GetObjectItemCaseSensitive(o,"valid"),*count=cJSON_GetObjectItemCaseSensitive(o,"count"),*pv=cJSON_GetObjectItemCaseSensitive(o,"pv"),*load=cJSON_GetObjectItemCaseSensitive(o,"load"),*grid=cJSON_GetObjectItemCaseSensitive(o,"grid"),*bat=cJSON_GetObjectItemCaseSensitive(o,"battery"),*en=cJSON_GetObjectItemCaseSensitive(o,"energy");if(!cJSON_IsBool(valid)||!cJSON_IsNumber(count)||!cJSON_IsNumber(pv)||!cJSON_IsNumber(load)||!cJSON_IsNumber(grid)||!cJSON_IsNumber(bat)||!tot_parse(en,&x.slots[i].energy))return false;x.slots[i].valid=cJSON_IsTrue(valid);x.slots[i].sample_count=count->valueint<0?0:(uint32_t)count->valuedouble;x.slots[i].pv_kw=(float)pv->valuedouble;x.slots[i].load_kw=(float)load->valuedouble;x.slots[i].grid_kw=(float)grid->valuedouble;x.slots[i].battery_kw=(float)bat->valuedouble;}x.valid=true;*out=x;return true;}
static esp_err_t load_day(const char *date,day_data_t *out){char path[64];path_for(date,path,sizeof(path));FILE *f=fopen(path,"rb");if(!f)return ESP_ERR_NOT_FOUND;fseek(f,0,SEEK_END);long sz=ftell(f);rewind(f);if(sz<=0||sz>STATS_FILE_MAX){fclose(f);return ESP_ERR_INVALID_SIZE;}char *b=malloc((size_t)sz+1);if(!b){fclose(f);return ESP_ERR_NO_MEM;}size_t n=fread(b,1,(size_t)sz,f);fclose(f);if(n!=(size_t)sz){free(b);return ESP_FAIL;}b[n]=0;cJSON *r=cJSON_Parse(b);free(b);bool ok=r&&day_parse(r,date,out);cJSON_Delete(r);return ok?ESP_OK:ESP_ERR_INVALID_ARG;}
static void corrupt(const char *date){char p[64],c[80];path_for(date,p,sizeof(p));snprintf(c,sizeof(c),"%s.corrupt",p);remove(c);rename(p,c);}
static esp_err_t save_locked(const day_data_t *d){if(!app_storage_is_ok())return ESP_ERR_INVALID_STATE;cJSON *r=day_json(d);if(!r)return ESP_ERR_NO_MEM;char *j=cJSON_PrintUnformatted(r);cJSON_Delete(r);if(!j)return ESP_ERR_NO_MEM;char path[64],tmp[72];path_for(d->date,path,sizeof(path));snprintf(tmp,sizeof(tmp),"%s.tmp",path);FILE *f=fopen(tmp,"wb");if(!f){cJSON_free(j);app_storage_mark_fault("stats fájl megnyitás sikertelen");return ESP_FAIL;}size_t len=strlen(j);bool ok=fwrite(j,1,len,f)==len;cJSON_free(j);if(ok){fflush(f);fsync(fileno(f));}fclose(f);if(!ok){remove(tmp);app_storage_mark_fault("stats fájl írás sikertelen");return ESP_FAIL;}remove(path);if(rename(tmp,path)){remove(tmp);app_storage_mark_fault("stats fájl cseréje sikertelen");return ESP_FAIL;}return ESP_OK;}
static void reset_today(const char *date){memset(&s_today,0,sizeof(s_today));snprintf(s_today.date,sizeof(s_today.date),"%s",date);s_today.valid=true;s_have_prev=false;}
static void roll(time_t now){char d[11];date_for(now,d);if(!strcmp(d,s_today.date))return;if(s_today.valid&&app_storage_is_ok())(void)save_locked(&s_today);s_yesterday=s_today;reset_today(d);s_last_save_us=esp_timer_get_time();app_events_add(APP_EVENT_INFO,"Új nap indult: %s",d);}
static void cleanup(const char *today,const char *yesterday){DIR *dir=opendir(STATS_DIR);if(!dir)return;struct dirent *e;while((e=readdir(dir))){size_t n=strlen(e->d_name);if(n<15||strcmp(e->d_name+n-5,".json"))continue;char d[11]={0};memcpy(d,e->d_name,10);if(!strcmp(d,today)||!strcmp(d,yesterday))continue;char p[96];snprintf(p,sizeof(p),STATS_DIR "/%s",e->d_name);remove(p);}closedir(dir);}

esp_err_t app_stats_init(const app_config_t *cfg){if(!cfg)return ESP_ERR_INVALID_ARG;if(!s_mutex)s_mutex=xSemaphoreCreateMutex();s_cfg=*cfg;if(mkdir(STATS_DIR,0775)!=0&&errno!=EEXIST){app_storage_mark_fault("stats könyvtár nem hozható létre");return ESP_FAIL;}time_t now=time(NULL);char td[11],yd[11];date_for(now,td);yesterday_for(now,yd);xSemaphoreTake(s_mutex,portMAX_DELAY);memset(&s_today,0,sizeof(s_today));memset(&s_yesterday,0,sizeof(s_yesterday));esp_err_t e=load_day(td,&s_today);if(e!=ESP_OK){if(e!=ESP_ERR_NOT_FOUND){corrupt(td);app_events_add(APP_EVENT_WARNING,"Sérült mai statisztika archiválva; a nap nulláról indul.");}reset_today(td);}e=load_day(yd,&s_yesterday);if(e!=ESP_OK){if(e!=ESP_ERR_NOT_FOUND){corrupt(yd);app_events_add(APP_EVENT_WARNING,"Sérült tegnapi statisztika archiválva; összehasonlítás kikapcsolva.");}memset(&s_yesterday,0,sizeof(s_yesterday));}cleanup(td,yd);s_have_prev=false;s_last_save_us=esp_timer_get_time();xSemaphoreGive(s_mutex);return ESP_OK;}
void app_stats_process_sample(const app_energy_sample_t *s){if(!s||!s_mutex)return;time_t now=(time_t)s->received_epoch_s;xSemaphoreTake(s_mutex,portMAX_DELAY);roll(now);int slot=slot_for(now);if(slot>=0&&slot<APP_STATS_SLOT_COUNT)avg(&s_today.slots[slot],s);if(s_have_prev){double dt=(double)(s->received_epoch_s-s_prev.received_epoch_s);if(dt>0&&dt<=(double)s_cfg.statistics.max_integration_gap_seconds){app_energy_totals_t e=energy(&s_prev,s,dt/3600.0);add(&s_today.totals,&e);int ps=slot_for((time_t)s_prev.received_epoch_s);if(ps==slot&&slot>=0&&slot<APP_STATS_SLOT_COUNT)add(&s_today.slots[slot].energy,&e);else if(ps>=0&&ps<APP_STATS_SLOT_COUNT)add(&s_today.slots[ps].energy,&e);}}s_prev=*s;s_have_prev=true;xSemaphoreGive(s_mutex);}
static void sum_completed(const day_data_t *d,int slots,app_energy_totals_t *out){memset(out,0,sizeof(*out));if(!d->valid)return;if(slots<0)slots=0;if(slots>APP_STATS_SLOT_COUNT)slots=APP_STATS_SLOT_COUNT;for(int i=0;i<slots;i++)add(out,&d->slots[i].energy);}
void app_stats_get_snapshot(app_stats_snapshot_t *o){if(!o||!s_mutex)return;int completed=slot_for(time(NULL));xSemaphoreTake(s_mutex,portMAX_DELAY);memset(o,0,sizeof(*o));snprintf(o->date,sizeof(o->date),"%s",s_today.date);o->totals=s_today.totals;memcpy(o->slots,s_today.slots,sizeof(o->slots));sum_completed(&s_today,completed,&o->completed_interval_totals);o->has_yesterday=s_yesterday.valid;if(s_yesterday.valid)sum_completed(&s_yesterday,completed,&o->yesterday_completed_interval_totals);xSemaphoreGive(s_mutex);}
esp_err_t app_stats_save_now(void){if(!s_mutex)return ESP_ERR_INVALID_STATE;xSemaphoreTake(s_mutex,portMAX_DELAY);esp_err_t e=save_locked(&s_today);if(e==ESP_OK)s_last_save_us=esp_timer_get_time();xSemaphoreGive(s_mutex);return e;}
static void stats_task(void *arg){(void)arg;while(true){time_t now=time(NULL);xSemaphoreTake(s_mutex,portMAX_DELAY);roll(now);bool due=(esp_timer_get_time()-s_last_save_us)>=(int64_t)s_cfg.statistics.save_interval_minutes*60LL*1000000LL;xSemaphoreGive(s_mutex);if(due&&app_storage_is_ok())(void)app_stats_save_now();vTaskDelay(pdMS_TO_TICKS(1000));}}
void app_stats_start_task(void){if(s_task_started)return;s_task_started=true;xTaskCreate(stats_task,"stats",6144,NULL,4,NULL);}
